import{_ as t,o as a,c as i,ah as o}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"The Pointillism of Capital","description":"","frontmatter":{},"headers":[],"relativePath":"en/pointillismus.md","filePath":"en/pointillismus.md"}'),n={name:"en/pointillismus.md"};function s(r,e,l,h,c,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="the-pointillism-of-capital" tabindex="-1">The Pointillism of Capital <a class="header-anchor" href="#the-pointillism-of-capital" aria-label="Permalink to &quot;The Pointillism of Capital&quot;">​</a></h1><p><strong>The Vision: Looking from a distance.</strong></p><p>Inspired by the artistic movement of Pointillism, our mockumentary develops its very own &quot;Theory of Money.&quot;</p><h2 id="the-principle" tabindex="-1">The Principle <a class="header-anchor" href="#the-principle" aria-label="Permalink to &quot;The Principle&quot;">​</a></h2><p>In the late 19th century, painters like Georges Seurat and Paul Signac revolutionized the world. They didn&#39;t mix colors on the palette, but applied them in small, pure dots of color to the canvas. Only from a distance do these dots merge into a complete, shimmering image.</p><h2 id="the-transfer-capital-and-politics" tabindex="-1">The Transfer: Capital and Politics <a class="header-anchor" href="#the-transfer-capital-and-politics" aria-label="Permalink to &quot;The Transfer: Capital and Politics&quot;">​</a></h2><p>We transfer this aesthetic principle to the wealth and political influence of the Hortens.</p><ul><li><strong>Helmut Horten:</strong> His wealth didn&#39;t fall from the sky. It&#39;s a mosaic of thousands of &quot;Aryanized&quot; department stores, small acquisitions, and opportunistic &quot;market optimizations&quot; during the 1930s. Each store is a dot.</li><li><strong>Heidi Horten:</strong> Her political donations were a masterpiece of Pointillism. Not one big, eye-catching sum, but many &quot;small&quot; 49,000-euro tranches. For the unsuspecting observer (like the Court of Audit), they look like harmless specks. Only from a distance do they form a clear picture of power.</li></ul><h2 id="the-aesthetic-of-the-mockumentary" tabindex="-1">The Aesthetic of the Mockumentary <a class="header-anchor" href="#the-aesthetic-of-the-mockumentary" aria-label="Permalink to &quot;The Aesthetic of the Mockumentary&quot;">​</a></h2><p>The &quot;Pointillism of Capital&quot; is the visual and narrative red thread of our film. We don&#39;t show the one big scandal. We show the many small, perfectly placed dots that, when combined, form a masterpiece of concealment.</p><hr><p><em>Because sometimes you have to step back to see the true price.</em></p>',12)])])}const u=t(n,[["render",s]]);export{d as __pageData,u as default};
